tree.custom.scss:
@use "./quartzcontrol";
.mine { background: url("/static/fonts/keep.woff2"); }
/* --- QuartzControl:managed:fonts:start --- */
@font-face {
  font-family: "A";
  src: url("/static/fonts/a.woff2") format("woff2");
}
@font-face {
  src: url( '/static/fonts/b.woff2'), url(/static/fonts/c.ttf);
}
/* --- QuartzControl:managed:fonts:end --- */

